  async function setOnline(value,forced){if(!value&&!forced&&activeJobs().length){toast("Finish or hand off the active delivery before going offline.","danger");return}if(value&&(!state.location.granted||!state.location.enabled||!Number.isFinite(Number(state.location.lat))||!Number.isFinite(Number(state.location.lng))||!Number.isFinite(Number(state.location.accuracy))||Number(state.location.accuracy)>100)){requestLocation(true);return}if(!state.network){if(!value){const preserveTracking=shouldPreserveActiveDeliveryTracking();state.online=false;setPendingOffline(true);if(!preserveTracking)stopTracking("offline");toast(preserveTracking?"Internet was lost. Active delivery tracking will retry automatically while new jobs stay paused.":"You are offline on this device. Scraveit will confirm it when internet returns.","danger");render({preserve:true})}else toast("Reconnect before going online.","danger");return}const current=primaryActiveJob(),record={online:!!value,riderId:state.session.uid,riderName:state.profile.fullName||state.session.email,updatedAt:Date.now(),city:state.profile.city||"",activeOrderId:value&&current?String(current.id||"").slice(0,80):""};if(value){record.lat=Number(state.location.lat);record.lng=Number(state.location.lng);record.accuracy=Number(state.location.accuracy)}try{await rtdb("PUT",ROOT+"/riderPresence/"+state.session.uid,record);state.online=!!value;setPendingOffline(false);if(!value)stopTracking("offline");else if(!current)await startAvailabilityTracking();toast(value?"You are online for nearby delivery offers.":"You are offline.",value?"success":"");render({preserve:true});if(value)setTimeout(()=>loadRiderRewards(true,Date.now()),1500)}catch(e){if(!value){state.online=false;setPendingOffline(true);stopTracking("offline")}toast(friendly(e),"danger")}}
  function navigationTarget(location,fallback){const lat=Number(location&&location.lat),lng=Number(location&&location.lng);if(Number.isFinite(lat)&&Number.isFinite(lng)&&(lat!==0||lng!==0))return lat+","+lng;return(location&&location.address)||fallback||""}
  function openNavigation(destination){if(!destination){toast("Navigation destination is missing.","danger");return}if(window.FeastlyRiderNative&&FeastlyRiderNative.openNavigation)FeastlyRiderNative.openNavigation(String(destination));else toast("Navigation is available in the installed app.","danger")}
  async function startAvailabilityTracking(){if(!state.online||primaryActiveJob()||!state.location.granted||!state.location.enabled)return false;try{const s=await ensure(),native=window.FeastlyRiderNative;if(!native||!native.startAvailabilityTracking)throw new Error("NATIVE_AVAILABILITY_UNAVAILABLE");native.startAvailabilityTracking(state.session.uid,state.profile.fullName||"Scraveit Partner",s.idToken,s.refreshToken||"",CONFIG.apiKey||"",state.profile.city||"");state.availabilityTracking=true;state.trackingError="";return true}catch(e){state.availabilityTracking=false;state.trackingError="Background availability could not start. "+friendly(e);render({preserve:true});return false}}
  async function startTracking(o,phase){if(!o||!state.location.granted||!state.location.enabled)return false;const nextPhase=String(phase||trackingPhaseForJob(o)||"pickup");if(trackingSessionHeld(o,nextPhase)&&["starting","active"].includes(String(state.trackingNativeState||""))){state.trackingError="";return true}try{const s=await ensure(),address=o.address||{},lat=Number(address.lat),lng=Number(address.lng),riderName=state.profile.fullName||"Scraveit Partner",native=window.FeastlyRiderNative;if(native&&native.startResilientTracking)native.startResilientTracking(o.userId,o.id,o.restaurantId||"",state.session.uid,riderName,s.idToken,s.refreshToken||"",CONFIG.apiKey||"",Number.isFinite(lat)?lat:0,Number.isFinite(lng)?lng:0,nextPhase,state.profile.city||"",o.status||"");else if(native&&native.startAdvancedTracking)native.startAdvancedTracking(o.userId,o.id,o.restaurantId||"",state.session.uid,riderName,s.idToken,s.refreshToken||"",CONFIG.apiKey||"",Number.isFinite(lat)?lat:0,Number.isFinite(lng)?lng:0,nextPhase);else throw new Error("NATIVE_TRACKING_UNAVAILABLE");state.availabilityTracking=false;state.trackingNativeState="starting";persistActiveTracking(o,nextPhase);state.trackingError="";return true}catch(e){state.trackingNativeState="stopped";state.trackingError="Secure live tracking could not start. "+friendly(e);toast(state.trackingError,"danger");render({preserve:true});return false}}
  function stopTracking(reason){const native=window.FeastlyRiderNative;/* Any reason but "offline" keeps the service running in online mode, so a rider waiting to go offline says so. */if(state.pendingOffline)reason="offline";try{if(native&&native.stopDeliveryTrackingWithReason)native.stopDeliveryTrackingWithReason(reason||"stopped");else if(native&&native.stopDeliveryTracking)native.stopDeliveryTracking()}catch(_){}state.availabilityTracking=false;state.trackingNativeState="stopped";persistActiveTracking(null);state.trackingError=""}
  function scheduleTrackingRecovery(){clearTimeout(state.trackingRecoveryTimer);state.trackingRecoveryTimer=setTimeout(async()=>{const current=primaryActiveJob(),native=window.FeastlyRiderNative;if(waitingForRestaurantHandover(current)){quiesceRestaurantWaitTracking(current);render({preserve:true});return}if(!state.session||!state.network||!state.online||!current||!native)return;try{const s=await ensure();if(typeof native.refreshDeliveryTrackingCredentials==="function")native.refreshDeliveryTrackingCredentials(s.idToken,s.refreshToken||"",CONFIG.apiKey||"");await startTracking(current,trackingPhaseForJob(current));await syncApproved(true).catch(()=>{})}catch(_){}},1500)}
  function arrivalVerificationPendingMessage(message){return/already in progress|being checked/i.test(String(message||""))}
  function hasVerifiedRestaurantArrival(orderId){const pointer=state.jobPointers[orderId]||{},current=job(orderId);return pointer.phase==="at_restaurant"||Number(pointer.arrivedRestaurantAt||0)>0||!!(pointer.arrivalVerification&&pointer.arrivalVerification.verified)||!!(current&&["Handed to rider","Out for delivery","Near you","Arrived","Delivered"].includes(current.status))}
  // A live face compare against this rider's own signup photo, required
  // before every session reaches "jobs" - not just the first one. Blocking
  // this on a screen with no back/skip is deliberate: an approved rider
  // must confirm it's really them before anything about their account (job
  // offers, location sharing, earnings) becomes reachable this session.
  // The Google Play review account (playReviewAccount, set only by admin) skips the
  // face scan when going online: reviewers can't match a real rider's face.
  function screenFaceVerifyLogin(){const enrolling=loginFaceCheckIsEnrollment();if(!enrolling)setTimeout(warmFaceVerifier,0);const copy=enrolling?{eyebrow:"One-time setup",title:"Set up identity verification",body:"Scraveit Partner confirms it's really you each time you go online. Take a quick live photo once to set this up - it will be compared automatically from now on."}:{eyebrow:"Confirm it's you",title:"Scan to go online",body:"Take a quick live photo so we know this is really you before you get orders."};return'<main class="screen no-nav"><div class="content" style="max-width:520px"><div class="stack-lg"><div class="cluster auth-top">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Quick identity check</p></div></div><div><p class="eyebrow">'+h(copy.eyebrow)+'</p><h1 class="display" style="margin-top:7px">'+h(copy.title)+'</h1><p class="supporting" style="font-size:15px;margin-top:11px">'+h(copy.body)+'</p></div>'+(state.faceCheckError?'<div class="notice danger">'+icon("warning","small")+'<div><strong>Could not verify</strong><div class="caption">'+h(state.faceCheckError)+'</div></div></div>':'')+'<button type="button" class="button primary full" data-action="verify-login-face" '+(state.faceCheckPending?"disabled":"")+'>'+(state.faceCheckPending?'<span class="spinner"></span> Verifying…':icon("camera")+" Scan your face")+"</button></div></div></main>"}
  // A rider approved before face verification existed reaches this screen
  // with no reference photo on file at all - their first post-rollout login
  // has nothing to compare against, so it doubles as their one-time
  // enrollment (the same search-and-index call signup uses) instead of a
  // 1:1 compare. Every login after that already has a reference, so it goes
  // through the fast compare like normal. This also means an existing
  // duplicate account (created before this feature existed) gets caught the
  // first time either one of its owners logs back in.
  function loginFaceCheckIsEnrollment(){return state.profile.faceMatchStatus!=="unique"}
  async function verifyLoginFaceNow(){state.faceCheckError="";let photo;try{photo=await captureFace()}catch(e){state.faceCheckError=friendly(e);render({preserve:true});return}state.faceCheckPending=true;render({preserve:true});const enrolling=loginFaceCheckIsEnrollment();try{if(enrolling){const result=await cloudSubmitFaceCheck(photo);state.profile.faceMatchStatus=result&&result.status||"needs_review";persist();if(state.profile.faceMatchStatus!=="unique"){state.faceCheckError="Your photo needs a quick manual check by the team before you can continue. Please try again shortly or contact support.";return}}else{const result=await cloudVerifyLoginFace(photo);if(!result||!result.verified){state.faceCheckError="That didn't match. Try again facing the camera directly in good lighting.";return}}state.route="jobs";state.history=[];setOnline(true)}catch(e){state.faceCheckError=friendly(e)}finally{state.faceCheckPending=false;render({preserve:true})}}
  // Every switch from offline to online needs a live face match, so the person riding
  // is the account holder. Back from the scan just leaves the rider offline.
  /* "Allow all the time" + battery: Rider restarts itself while Online. Hidden in a build without the permission. */
  function backgroundAccess(){const native=window.FeastlyRiderNative;try{if(native&&native.backgroundAccessState)return JSON.parse(native.backgroundAccessState())}catch(_){}return null}
  function backgroundAccessMissing(){const access=backgroundAccess();return !!(access&&access.declared&&(access.location!=="all"||!access.battery))}
  window.riderBackgroundAccessChanged=function(){if(state.session&&(state.route==="backgroundAccess"||state.online))render({preserve:true})};
  function backgroundAccessStep(number,done,title,copy,action){return'<div class="bg-access-step'+(done?" done":"")+'"><div class="bg-access-number">'+(done?"✓":number)+'</div><div class="grow"><strong>'+h(title)+'</strong><div class="caption">'+h(copy)+'</div></div>'+(done?'<span class="bg-access-done">Done</span>':'<button type="button" class="button primary" data-action="'+action+'">Allow</button>')+'</div>'}
  function screenBackgroundAccess(){const access=backgroundAccess()||{},locationDone=access.location==="all",batteryDone=access.battery===true,ready=locationDone&&batteryDone;return'<main class="screen no-nav"><div class="content bg-access" style="max-width:520px"><div class="bg-access-icon">'+icon("pin")+'</div><h1 class="display">Stay online when the app is closed</h1><p class="supporting">'+h(BRAND)+' collects your location to find nearby delivery offers and show customers live tracking, even when the app is closed or not in use, while you are Online. It stops when you go Offline.</p>'+backgroundAccessStep(1,locationDone,"Location: Allow all the time",'On the next screen, choose "Allow all the time".',"bg-access-location")+backgroundAccessStep(2,batteryDone,"Battery: Unrestricted","So your phone doesn\'t stop offers while you use other apps.","bg-access-battery")+'<div class="bg-access-actions"><button type="button" class="button primary full" data-action="bg-access-continue" '+(ready?"":"disabled")+'>Continue</button><button type="button" class="text-button" data-action="bg-access-later">'+(state.online?"Not now":"Not now, stay Offline")+'</button></div></div></main>'}
  function finishBackgroundAccess(){if(backgroundAccessMissing())return;const thenOnline=state.backgroundAccessThenOnline===true;state.backgroundAccessThenOnline=false;go("jobs",{},true);if(thenOnline)goOnlineWithFaceCheck()}
  function goOnlineWithFaceCheck(){if(!locationNoticeAccepted()){state.locationNoticeResume="face";setSheet({type:"locationNotice"});return}if(backgroundAccessMissing()){state.backgroundAccessThenOnline=true;go("backgroundAccess");return}if(state.profile.playReviewAccount===true){setOnline(true);return}state.faceCheckError="";go("faceVerifyLogin")}
  function enterJobsAfterLoginCheck(){state.route="jobs";state.history=[];requestLocation(false);if(state.pendingOffline&&state.network)reconcilePendingOffline().catch(()=>{});startPoll();syncApproved(true).then(()=>render({preserve:true})).catch(e=>{state.error=friendly(e);render({preserve:true})});ensureNativePushRegistered(false)}
  function faceCheckMarkup(){const status=state.profile.faceMatchStatus||"";if(status==="unique")return'<div class="notice success">'+icon("check","small")+'<div><strong>Face scan done</strong></div></div>';if(status==="needs_review")return'<div class="notice warning">'+icon("shield","small")+'<div><strong>Manual check needed</strong><div class="caption">Your photo is being checked by the team - this can take a little time. You can retake it if the lighting was poor.</div></div></div><button type="button" class="button tonal full" data-action="scan-face" '+(state.faceCheckPending?"disabled":"")+'>Retake photo</button>';return'<button type="button" class="button tonal full" data-action="scan-face" '+(state.faceCheckPending?"disabled":"")+'>'+(state.faceCheckPending?'<span class="spinner"></span> Verifying…':icon("camera")+" Scan your face")+"</button>"+(state.faceCheckError?'<p class="supporting" style="color:var(--danger)">'+h(state.faceCheckError)+"</p>":"")}
  async function scanFaceForOnboarding(){state.faceCheckError="";let photo;try{photo=await captureFace()}catch(e){state.faceCheckError=friendly(e);render({preserve:true});return}state.faceCheckPending=true;render({preserve:true});try{const result=await cloudSubmitFaceCheck(photo);state.profile.faceMatchStatus=result&&result.status||"needs_review";persist();toast(state.profile.faceMatchStatus==="unique"?"Identity verified.":"Your photo needs a quick manual check.",state.profile.faceMatchStatus==="unique"?"success":"warning")}catch(e){state.faceCheckError=friendly(e);toast(friendly(e),"danger")}finally{state.faceCheckPending=false;render({preserve:true})}}
  async function settleRestaurantArrival(orderId){for(const waitMs of [1200,1800]){await new Promise(resolve=>setTimeout(resolve,waitMs));await syncApproved(true).catch(()=>{});if(hasVerifiedRestaurantArrival(orderId))return true}return hasVerifiedRestaurantArrival(orderId)}
  async function claimOffer(id){const offer=availableOffers().find(o=>o.id===id);if(state.pendingOfferAction)return;if(!offer||!state.online){closeSheet();toast(state.online?"This offer has expired or was assigned.":"Go online before accepting an offer.","danger");return}if(!canReserveNextDelivery(offer)){toast("Finish the current delivery before accepting another.","danger");return}if(!state.location.enabled){requestLocation(true);return}const extraPickup=!!offer.bundle,finishingCurrent=!extraPickup&&activeJobs().length===1;state.pendingOfferAction=id;pauseNativeOffer(offer);renderSheet();try{await cloudClaim(id)}catch(e){const stillAvailable=await recoverOfferAfterFailure(offer,e),message=friendly(e);toast(!stillAvailable&&terminalOfferFailure(message)?"This offer expired or was assigned to another delivery partner.":"Could not accept this offer. "+message,"danger");state.pendingOfferAction="";render({preserve:true});return}permanentlySilenceNativeOffer(offer);delete state.queue[id];try{await syncApproved(true);const current=job(id);if(current){state.selectedJobId=id;if(!finishingCurrent&&!extraPickup){await startTracking(current,"pickup");openNavigation(navigationTarget(current.restaurantLocation,offer.restaurantAddress));go("jobDetail",{jobId:id})}}closeSheet();toast(extraPickup&&offer.bundle.kind==="batch"?"Order added to your trip. Collect both orders, then deliver them one after the other.":extraPickup?"Pickup added to your trip. Collect it after "+((activeJobs().find(j=>j.id===offer.bundle.leadOrderId)||{}).restaurant||"the first restaurant")+", then deliver both together.":finishingCurrent?"Next delivery secured. Complete the doorstep delivery first.":"Delivery secured. Navigate to the restaurant.","success")}catch(e){closeSheet();toast("Delivery secured. Live details are reconnecting.","warning")}finally{state.pendingOfferAction="";render({preserve:true})}}
  async function declineOffer(id){if(!id||state.pendingOfferAction)return;const offer=availableOffers().find(o=>o.id===id);if(!offer){closeSheet();toast("This offer has already expired.","danger");return}state.pendingOfferAction=id;pauseNativeOffer(offer);renderSheet();try{await cloudDecline(id)}catch(e){await recoverOfferAfterFailure(offer,e);toast("Offer decline failed. "+friendly(e),"danger");state.pendingOfferAction="";render({preserve:true});return}permanentlySilenceNativeOffer(offer);delete state.queue[id];closeSheet();toast("Offer declined. Finding the next nearby delivery partner.","success");try{await syncApproved(true)}catch(_){toast("Offer declined. Delivery offers are reconnecting.","warning")}finally{state.pendingOfferAction="";render({preserve:true})}}
  /**
   * A stale "tracking is already running" client-side flag can survive a
   * native session that actually died, or one that was quietly never
   * started for this exact order (e.g. it became the rider's primary job
   * while the app was backgrounded, so nothing ever called startTracking()
   * for it) - startTracking()'s own no-op guard only checks that optimistic
   * bookkeeping, so calling it again does nothing in exactly the case that
   * needs a real restart. stopTracking() first clears that bookkeeping so
   * the following startTracking() issues a genuine fresh native call.
   */
  async function forceRestartTracking(o){
    stopTracking("recovering");
    await startTracking(o,trackingPhaseForJob(o));
    await heartbeat().catch(()=>{});
  }
  async function markAtRestaurant(o){if(!o||state.pendingJobAction)return;state.pendingJobAction=o.id;render({preserve:true});try{const result=await cloudMarkAtRestaurant(o.id);state.jobPointers[o.id]=Object.assign({},state.jobPointers[o.id],{phase:"at_restaurant",arrivedRestaurantAt:Number(result&&result.arrivedAt||Date.now()),arrivalVerification:{verified:true}});render({preserve:true});toast(result&&result.idempotent?"Restaurant arrival already verified.":"Arrival at restaurant verified.","success");await syncApproved(true)}catch(e){const message=friendly(e);if(arrivalVerificationPendingMessage(message)){toast("Checking restaurant arrival…","warning");if(await settleRestaurantArrival(o.id)){toast("Arrival at restaurant verified.","success");return}toast(state.trackingError?"Live location is reconnecting. Keep the app open and retry in a few seconds.":"Arrival check is still running. Keep the app open and retry in a few seconds.","warning");return}if(message==="Restaurant arrival could not be verified."){
    // The server had nothing (or stale/wrong-order data) to verify against -
    // most often because live tracking for THIS job never actually reached
    // it, regardless of what the app's own state believes. A generic
    // syncApproved() only restarts tracking if its own bookkeeping already
    // agrees it should, which is exactly what's wrong here - force a real
    // restart instead of leaving the rider stuck retapping a dead end.
    // Retry on its own while a fresh, accurate fix arrives, instead of
    // making the rider tap again and again. Same server check every time.
    toast("Confirming your location at the restaurant…","warning");
    await forceRestartTracking(o).catch(()=>{});
    for(const waitMs of [2500,3000,4000,5000,6000]){
      await new Promise(resolve=>setTimeout(resolve,waitMs));
      try{const retry=await cloudMarkAtRestaurant(o.id);state.jobPointers[o.id]=Object.assign({},state.jobPointers[o.id],{phase:"at_restaurant",arrivedRestaurantAt:Number(retry&&retry.arrivedAt||Date.now()),arrivalVerification:{verified:true}});render({preserve:true});toast("Arrival at restaurant verified.","success");syncApproved(true).catch(()=>{});return}
      catch(retryError){if(friendly(retryError)!=="Restaurant arrival could not be verified."&&!arrivalVerificationPendingMessage(friendly(retryError)))break}
    }
    await syncApproved(true).catch(()=>{});
    toast("We could not confirm you are at the restaurant yet. Move closer to the entrance or step outside for a clearer GPS signal, then tap arrived again.","warning");
    return;
  }toast(message,"danger")}finally{state.pendingJobAction="";render({preserve:true})}}
  async function updateStatus(o,status){const valid=o.status==="Handed to rider"&&status==="Out for delivery";if(!valid){toast("That delivery step is not available yet.","danger");return false}if(batchHold(o)){toast(batchHold(o),"warning");return false}if(state.pendingJobAction)return false;state.pendingJobAction=o.id;render({preserve:true});try{await cloudStatus(o,status,{});o.status=status;o.updatedAt=Date.now();await startTracking(o,"delivery");openNavigation(navigationTarget(o.address,o.address&&o.address.details));toast("Delivery moved to "+status+".","success");return true}catch(e){toast("Status update failed. "+friendly(e),"danger");await syncApproved(true).catch(()=>{});return false}finally{state.pendingJobAction="";render({preserve:true})}}
  // The server confirms arrival from two GPS readings near the door. "Checking" stays on screen until
  // that lands, then the OTP box opens by itself, so one swipe is enough.
  async function confirmDeliveryLocation(o){if(!o||!["Out for delivery","Near you"].includes(o.status))return;if(state.pendingJobAction)return;state.pendingJobAction=o.id;render({preserve:true});let arrived=false;try{const started=await startTracking(o,"delivery");if(!started){toast("Live location could not start. Keep Location on and try again.","danger");return}heartbeat().catch(()=>{});
    // A college or hospital stops the partner at the gate, far from the pin, and the customer is often
    // already waiting there. The swipe asks the server: it opens the OTP box at once when it sees the
    // partner at that campus, and changes nothing for any other order.
    let gate=false,gateAsks=0;const askGate=()=>{gateAsks++;cloudStatus(o,"Arrived").then(()=>{gate=true}).catch(()=>{})};askGate();
    const startedAt=Date.now(),giveUpAt=startedAt+15000;while(Date.now()<giveUpAt){for(let i=0;i<4&&!gate;i++)await new Promise(done=>setTimeout(done,500));await syncApproved(true).catch(()=>{});const latest=job(o.id);if(!latest)break;if(gate&&["Out for delivery","Near you"].includes(latest.status))latest.status="Arrived";if(latest.status==="Arrived"){arrived=true;break}if(gateAsks<2&&Date.now()-startedAt>6500)askGate()}if(!arrived&&job(o.id))toast("Not confirmed yet. Go to the customer's location pin and swipe again.","warning")}finally{state.pendingJobAction="";if(arrived)setSheet({type:"complete",jobId:o.id});else render({preserve:true})}}
  async function completeDelivery(o,otp,cashConfirmed,form){if(o.status!=="Arrived"){toast("Record arrival at the delivery location before completion.","danger");return}if(o.otpRequired!==true&&o.legacyOtpOrderSuffix!==true){toast("Delivery verification is unavailable for this order. Refresh or contact support.","danger");return}if(o.paymentMethod==="cod"&&!cashConfirmed){toast("Confirm cash collection before completing COD delivery.","danger");return}if(!/^\d{4,6}$/.test(String(otp||""))){toast("Enter the delivery OTP shown by the customer.","danger");return}const submitButton=form&&form.querySelector('button[type="submit"]'),originalButtonLabel=submitButton?submitButton.textContent:"";if(submitButton){submitButton.disabled=true;submitButton.innerHTML='<span class="spinner"></span> Verifying…'}try{await cloudStatus(o,"Delivered",{deliveryOtp:String(otp),cashCollected:!!cashConfirmed});o.status="Delivered";o.deliveredAt=Date.now();state.rewardsWeekPreview=null;state.rewardsDayKey=earningDateKey();state.rewardsReferenceAt=Date.now();state.rewardsLastSync=0;stopTracking("delivered");closeSheet();toast("Delivery completed and recorded.","success");go("earnings",{},true)}catch(e){toast("Delivery completion failed. "+friendly(e),"danger");if(submitButton){submitButton.disabled=false;submitButton.textContent=originalButtonLabel||"Verify and mark delivered"}}}

  function screenLaunch(){return '<main class="screen no-nav"><div class="content launch"><span class="spinner"></span><strong>Restoring your partner workspace…</strong></div></main>';}
  function screenWelcome(){return'<main class="screen no-nav welcome-fit"><div class="content wf-body"><div class="cluster auth-top">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Deliver with confidence</p></div></div><section class="card hero wf-hero"><div class="stack"><span class="status" style="background:rgba(255,255,255,.16);color:white">PARTNER NETWORK</span><h1 class="display">Clear jobs.<br>Safer journeys.</h1><p class="supporting" style="color:rgba(255,255,255,.82)">Apply securely, control your availability and complete every delivery one step at a time.</p></div></section><div class="stack"><button class="button primary full" data-action="go" data-route="signup">Apply as a delivery partner</button><button class="button tonal full" data-action="go" data-route="login">I already have an account</button><p class="caption" style="text-align:center">Your location is shared only while you are online or on a delivery, even when the app is closed or not in use.</p>'+privacyTapLine()+'</div></div></main>'}
  function screenLogin(){return'<main class="screen no-nav login-fit"><div class="content" style="max-width:520px"><div class="stack-lg"><div class="cluster auth-top">'+logo()+'<div><div class="brand">'+BRAND+'</div><p class="caption">Approved partner access</p></div></div><div><p class="eyebrow">Welcome back</p><h1 class="display" style="margin-top:7px">Ready for the next journey?</h1><p class="supporting" style="font-size:15px;margin-top:11px">Manage availability, deliveries and earnings.</p></div>'+banner()+'<form id="login-form" class="card form-grid"><div class="field"><label>Email address</label><input class="input" name="email" type="email" inputmode="email" autocomplete="email" required></div><div class="field"><label>Password</label><input class="input" name="password" type="password" autocomplete="current-password" required></div><button class="button primary full" type="submit" '+(state.loading?'disabled':'')+'>'+(state.loading?'<span class="spinner"></span> Signing in…':'Sign in securely')+'</button><button class="text-button" type="button" data-action="reset-password">Forgot password?</button><div class="divider">or</div><div class="field"><label>Referral code (new partners, optional)</label><input class="input" id="login-referral-code" placeholder="6-digit code or referral link"></div>'+appleButton("button full")+'<button class="button tonal full" type="button" data-action="google-signin" '+(state.loading?'disabled':'')+'>Continue with Google</button></form>'+privacyTapLine()+'<p class="supporting" style="text-align:center">New partner? <button class="text-button" data-action="go" data-route="signup">Create an application</button></p></div></div></main>'}
  function screenSignup(){return'<main class="screen no-nav signup-page"><div class="content page">'+top("Create partner account","Start your secure delivery-partner application.")+'<form id="signup-form" class="card form-grid"><div class="field"><label>Full name</label><input class="input" name="name" autocomplete="name" required></div><div class="field"><label>Email address</label><input class="input" name="email" type="email" inputmode="email" autocomplete="email" required></div><div class="field"><label>Mobile number</label><input class="input" name="phone" type="tel" inputmode="tel" autocomplete="tel" required></div><div class="field"><label>Create password</label><input class="input" name="password" type="password" minlength="8" autocomplete="new-password" required><p class="caption">Use 8+ characters with letters and numbers.</p></div><div class="field"><label>Confirm password</label><input class="input" name="confirm" type="password" autocomplete="new-password" required></div><div class="field"><label>Referral code or link (optional)</label><input class="input" name="referredByCode" value="'+h(installReferralCode())+'" placeholder="6-digit code or referral link"><p class="caption">Have a delivery partner referral code? Enter it here. Your inviter is rewarded only after you complete the required number of successful deliveries. Once your application is submitted, the code cannot be changed.</p></div>'+'<button class="button primary full" type="submit">Create account and continue</button>'+privacyTapLine()+'</form></div></main>'}
  // A driving licence is needed for every motor vehicle (Motor Vehicles Act 1988, s.3); a bicycle needs none.
  function dlValid(v){return/^[A-Z]{2}[0-9]{2}[0-9A-Z]{9,12}$/.test(String(v||"").toUpperCase().replace(/[^A-Z0-9]/g,""))}
  function todayIst(){return new Date(Date.now()+5.5*3600e3).toISOString().slice(0,10)}
  function vehicleLicenceFields(v){if(draftValue("vehicleType",state.profile.vehicleType||"Motorcycle")==="Bicycle")return'<p class="caption">A bicycle needs no registration number or driving licence.</p>';
    const dl=draftValue("dlNumber",state.profile.dlNumber||"");
    return'<div class="field"><label>Vehicle registration</label><input class="input" name="vehicleNumber" value="'+v("vehicleNumber",state.profile.vehicleNumber||"")+'" placeholder="AP 00 AB 0000" required></div>'
      +'<div class="field"><label>Driving licence number</label><input class="input dl-input" name="dlNumber" maxlength="16" autocapitalize="characters" autocomplete="off" value="'+v("dlNumber",state.profile.dlNumber||"")+'" placeholder="AP0320210012345" required><span class="caption'+(dl&&dlValid(dl)?' ok':'')+'" id="dl-hint">'+(dl&&dlValid(dl)?'Looks right ✓':dl?'Should look like AP0320210012345':'As printed on your licence, without spaces')+'</span></div>'
      +'<div class="field"><label>Licence valid till</label><input class="input" type="date" name="dlValidTill" min="'+todayIst()+'" value="'+v("dlValidTill",state.profile.dlValidTill||"")+'" required><span class="caption">The “Validity (NT)” date on your licence</span></div>'
      +docCard("dlFront","Driving licence, front","Your photo, name and licence number readable")
      +docCard("dlBack","Driving licence, back","The vehicle classes (like MCWG) readable")}
  function docCard(key,title,copy){const data=state.documentDraft[key];return'<article class="card document-card"><div class="cluster between"><div><h3 class="card-title">'+h(title)+'</h3><p class="supporting">'+h(copy)+'</p></div><span class="status '+(data?'success':'warning')+'">'+(data?'Ready':'Required')+'</span></div><div class="document-preview" id="preview-'+key+'">'+(data?'<img src="'+h(data)+'" alt="'+h(title)+' preview">':icon("document","large"))+'</div><label class="button tonal full">'+icon("camera")+' '+(data?'Retake photo':'Take or choose a photo')+'<input class="sr-only document-input" type="file" accept="image/jpeg,image/png,image/webp" data-document="'+key+'"></label></article>'}

  // ===== Identity: Aadhaar Secure QR (UIDAI-signed) + face + PAN =====
  // No Aadhaar photocopies: the rider scans the QR on their own Aadhaar and
  // the server checks UIDAI's digital signature. Only the last 4 digits of
  // the Aadhaar number ever reach Scraveit.
  const IDENTITY_CONSENT_VERSION="rider-identity-v4";
  function identityState(){const p=state.profile||{},id=p.identity||{};return{aadhaar:state.aadhaarResult||(id.aadhaar&&id.aadhaar.verified?{name:id.aadhaar.name,last4:id.aadhaar.last4,birthYear:id.aadhaar.birthYear,district:id.aadhaar.district,state:id.aadhaar.state}:null),fallback:state.identityFallback||p.identityFallback==="manual",consented:state.identityConsented||p.identityConsentVersion===IDENTITY_CONSENT_VERSION}}
  function panValid(v){return/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(String(v||"").toUpperCase())}
  function stepTile(n,done,title,copy,body){return'<section class="id-step'+(done?' done':'')+'"><div class="id-step-head"><span class="id-step-num">'+(done?icon("check","small"):n)+'</span><div class="grow"><h3>'+h(title)+'</h3><p>'+h(copy)+'</p></div></div>'+(body?'<div class="id-step-body">'+body+'</div>':'')+'</section>'}
  function aadhaarStepBody(){
    const s=identityState();
    if(s.aadhaar)return'<div class="id-verified"><span class="id-badge">'+icon("shield","small")+' Verified with UIDAI</span><strong>'+h(s.aadhaar.name)+'</strong><span>Aadhaar •••• '+h(s.aadhaar.last4)+(s.aadhaar.birthYear?' · born '+h(s.aadhaar.birthYear):'')+(s.aadhaar.district?' · '+h(s.aadhaar.district):'')+'</span></div>';
    if(s.fallback)return'<p class="caption">You chose a manual check. Add a <b>masked</b> Aadhaar (first 8 digits hidden). It can take up to a day. <button type="button" class="text-button" data-action="id-use-qr">Scan the QR instead</button></p>'+docCard("aadhaarFront","Aadhaar, front","Masked copy, first 8 digits hidden")+docCard("aadhaarBack","Aadhaar, back","Address side");
    if(state.aadhaarBusy)return'<div class="id-busy"><span class="spinner"></span><span>Checking with UIDAI’s digital signature…</span></div>';
    return'<div class="id-qr-art" aria-hidden="true"><span></span></div><div class="id-actions"><button type="button" class="button primary grow" data-action="id-scan-qr">'+icon("camera")+' Scan Aadhaar QR</button><label class="button tonal grow">'+icon("document")+' Upload e-Aadhaar<input class="sr-only aadhaar-qr-input" type="file" accept="image/*"></label></div>'
      +(state.aadhaarError?'<div class="notice danger">'+icon("warning","small")+'<span>'+h(state.aadhaarError)+'</span></div>':'')
      +'<p class="caption">The QR is on the back of your Aadhaar card or letter, and on your e-Aadhaar (download it free at myaadhaar.uidai.gov.in). For e-Aadhaar, zoom in until the big QR fills your screen, then take a screenshot. <button type="button" class="text-button" data-action="id-manual">My Aadhaar has no QR</button></p>';
  }
  function identitySection(){
    const s=identityState(),face=state.profile.faceMatchStatus==="unique"||state.profile.faceMatchStatus==="needs_review",pan=draftValue("panNumber",state.profile.panNumber||""),panOk=panValid(pan)&&!!state.documentDraft.panCopy;
    return'<section class="card stack id-card"><div><p class="eyebrow">Identity · about 2 minutes</p><h2 class="section-title">Verify it’s you</h2><p class="supporting">Three quick steps. Your details are checked with UIDAI and kept private. <button type="button" class="text-button" data-action="privacy-notice">How we use your data</button></p></div>'
      +stepTile(1,!!s.aadhaar,"Aadhaar","Scan the QR code on your Aadhaar. No photocopy needed.",aadhaarStepBody())
      +stepTile(2,state.profile.faceMatchStatus==="unique","Face scan","A live photo, matched to your Aadhaar photo.",faceCheckMarkup())
      +stepTile(3,panOk,"PAN","Needed for tax on your earnings.",'<div class="field"><label>PAN number</label><input class="input pan-input" name="panNumber" maxlength="10" autocapitalize="characters" autocomplete="off" value="'+h(pan)+'" placeholder="ABCPE1234F" required><span class="caption" id="pan-hint">'+(pan&&!panValid(pan)?'Should look like ABCPE1234F':'10 characters, as printed on your PAN card')+'</span></div>'+docCard("panCopy","PAN card photo","Front side, all text readable"))
      +'</section>';
  }
  function privacyNoticeSheet(){
    return sheetShell("Your data, explained","How Scraveit verifies delivery partners",'<div class="privacy-notice">'
      +'<h3>What we check</h3><p>Your Aadhaar’s secure QR code (we check UIDAI’s digital signature to confirm it’s genuine), a live face photo matched to the photo in that QR, your PAN, and for a motor vehicle your driving licence.</p>'
      +'<h3>What we keep</h3><p>Your name, date of birth, gender, district and state, the <b>last 4 digits</b> of your Aadhaar, your PAN, your driving licence number, valid-till date and photos, your face photo (used to confirm it’s you when you sign in) and the result of each check. We never see or store your full Aadhaar number.</p>'
      +'<h3>What we delete</h3><p>The photo from your Aadhaar QR, and any Aadhaar images you upload, are deleted 7 days after your application is decided.</p>'
      +'<h3>Why</h3><p>To confirm your identity and age (18+), that you may legally ride, to keep one account per person, to deduct and report tax on your earnings, and to register you as a platform worker as the Code on Social Security, 2020 requires.</p>'
      +'<h3>Who sees it</h3><p>Only Scraveit’s verification team, through short-lived, logged links. Face matching runs on Amazon Web Services in Mumbai, India. We don’t sell your data.</p>'
      +'<h3>Your rights</h3><p>You can ask to see, correct or delete your data, or withdraw consent, at any time from Support in the app. Withdrawing consent ends your partner account, because we can’t pay or insure an unverified partner. Grievances: Support › Privacy.</p>'
      +'<p class="caption">Under the Digital Personal Data Protection Act, 2023. Notice version '+IDENTITY_CONSENT_VERSION+'.</p></div>'
      +'<button class="button primary full" data-action="id-consent-accept">I agree</button>');
  }
  async function verifyAadhaarQr(raw){
    state.aadhaarError="";state.aadhaarBusy=true;render({preserve:true});
    try{const s=await ensure(),res=await nativeInvoke("verifyRiderAadhaarQr",[s.idToken,JSON.stringify({qrData:String(raw),consentVersion:IDENTITY_CONSENT_VERSION})],65000),r=typeof res==="string"?JSON.parse(res):res,data=r&&r.result||r&&r.data||r;
      state.aadhaarResult=data;state.aadhaarBusy=false;state.identityFallback=false;
      const form=document.getElementById("onboarding-form");if(form){const name=form.querySelector('[name="fullName"]');if(name&&!name.value&&data&&data.name)name.value=data.name}
      try{window.FeastlyRiderNative&&FeastlyRiderNative.vibrateSuccess&&FeastlyRiderNative.vibrateSuccess()}catch(_){}
      toast("Aadhaar verified with UIDAI.","success");render({preserve:true})}
    catch(e){state.aadhaarBusy=false;state.aadhaarError=friendly(e);render({preserve:true})}
  }
  window.aadhaarQrRead=function(result){
    const raw=result&&result.raw||"",error=result&&result.error||"";
    if(error==="cancelled")return;
    if(!raw){state.aadhaarBusy=false;state.aadhaarError=error||"No QR found. Try again.";render({preserve:true});return}
    if(!/^\d{200,}$/.test(raw)){state.aadhaarBusy=false;state.aadhaarError="That’s not the Aadhaar secure QR. Use the big QR code on your Aadhaar (not a payment QR).";render({preserve:true});return}
    verifyAadhaarQr(raw);
  };
  function startAadhaarScan(fromUpload){
    if(!identityState().consented){state.pendingIdAction=fromUpload?"upload":"scan";setSheet({type:"privacy"});return false}
    if(!fromUpload){if(window.FeastlyRiderNative&&FeastlyRiderNative.scanAadhaarQr){state.aadhaarError="";FeastlyRiderNative.scanAadhaarQr()}else toast("Update the Scraveit Partner app to scan your Aadhaar.","danger")}
    return true;
  }
  function handleIdentityClick(a,c){
    if(a==="id-scan-qr"){captureApplicationDraft(document.getElementById("onboarding-form"));startAadhaarScan(false);return true}
    if(a==="id-manual"){captureApplicationDraft(document.getElementById("onboarding-form"));state.identityFallback=true;render({preserve:true});return true}
    if(a==="id-use-qr"){captureApplicationDraft(document.getElementById("onboarding-form"));state.identityFallback=false;render({preserve:true});return true}
    if(a==="privacy-notice"){setSheet({type:"privacy"});return true}
    if(a==="id-consent-accept"){state.identityConsented=true;const next=state.pendingIdAction;state.pendingIdAction="";closeSheet();if(next==="scan")startAadhaarScan(false);else if(next==="upload"){const file=state.pendingAadhaarFile;state.pendingAadhaarFile=null;if(file){readAadhaarFile(file);return true}toast("Thanks. Now choose your e-Aadhaar screenshot.","success")}render({preserve:true});return true}
    return false;
  }
  document.addEventListener("change",event=>{
    const input=event.target&&event.target.closest&&event.target.closest(".aadhaar-qr-input");if(!input)return;
    const file=input.files&&input.files[0];input.value="";if(!file)return;
    // A picture chosen before consent is kept and read as soon as the rider agrees.
    if(!identityState().consented){state.pendingAadhaarFile=file;state.pendingIdAction="upload";setSheet({type:"privacy"});return}
    readAadhaarFile(file);
  });
  function readAadhaarFile(file){
    if(!(window.FeastlyRiderNative&&FeastlyRiderNative.readAadhaarQrFromImage)){toast("Update the Scraveit Partner app to read your e-Aadhaar.","danger");return}
    const reader=new FileReader();reader.onload=()=>{const b64=String(reader.result||"").split(",")[1]||"";state.aadhaarError="";state.aadhaarBusy=true;render({preserve:true});FeastlyRiderNative.readAadhaarQrFromImage(b64);setTimeout(()=>{if(state.aadhaarBusy&&!state.aadhaarResult){state.aadhaarBusy=false;render({preserve:true})}},70000)};reader.readAsDataURL(file);
  }
  // The parcel photo input lives outside #app. render() replaces everything inside #app, so a redraw
  // while the camera is open (back from another app, kitchen taps Order ready) would detach the input
  // and lose the photo with no error.
  const pickupPhotoInput=document.createElement("input");let pickupPhotoJobId="";pickupPhotoInput.id="pickup-photo-input";pickupPhotoInput.className="sr-only";pickupPhotoInput.type="file";pickupPhotoInput.accept="image/*";pickupPhotoInput.setAttribute("capture","environment");pickupPhotoInput.tabIndex=-1;pickupPhotoInput.setAttribute("aria-hidden","true");pickupPhotoInput.style.setProperty("position","fixed","important");pickupPhotoInput.style.top="0";pickupPhotoInput.style.left="0";document.body.appendChild(pickupPhotoInput);
  document.addEventListener("click",event=>{const label=event.target&&event.target.closest&&event.target.closest("[data-pickup-photo-job]");if(label)pickupPhotoJobId=label.dataset.pickupPhotoJob||""},true);
  pickupPhotoInput.addEventListener("change",()=>{const file=pickupPhotoInput.files&&pickupPhotoInput.files[0];pickupPhotoInput.value="";if(file)takePickupPhoto(pickupPhotoJobId,file)});
  document.addEventListener("input",event=>{const el=event.target;if(!el||!el.classList||!el.classList.contains("dl-input"))return;const v=el.value.toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,16);if(v!==el.value)el.value=v;const hint=document.getElementById("dl-hint");if(hint){const ok=dlValid(v);hint.textContent=v.length>=13?(ok?"Looks right ✓":"Should look like AP0320210012345"):"As printed on your licence, without spaces";hint.className="caption"+(ok?" ok":"")}});
  document.addEventListener("input",event=>{const el=event.target;if(!el||!el.classList||!el.classList.contains("pan-input"))return;const v=el.value.toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,10);if(v!==el.value)el.value=v;const hint=document.getElementById("pan-hint");if(hint){hint.textContent=v.length===10?(panValid(v)?"Looks right ✓":"Should look like ABCPE1234F"):"10 characters, as printed on your PAN card";hint.className="caption"+(v.length===10&&panValid(v)?" ok":"")}});

  function screenOnboarding(){const d=state.applicationDraft||{},v=(k,f)=>h(draftValue(k,f));return'<main class="screen no-nav apply-fit"><div class="content page">'+top("Partner application")+'<div class="stepper"><span class="step-dot done"></span><span class="step-dot done"></span><span class="step-dot"></span></div><div class="notice info">'+icon("shield","small")+'<span>Takes about 3 minutes. Keep your Aadhaar, PAN card and driving licence handy. Your progress is saved as you go.</span></div><form id="onboarding-form" class="stack-lg"><section class="card form-grid"><h2 class="section-title">Contact and city</h2><div class="field"><label>Full name</label><input class="input" name="fullName" value="'+v("fullName",state.profile.fullName||"")+'" required></div><div class="field"><label>Mobile number</label><input class="input" name="phone" type="tel" inputmode="tel" value="'+v("phone",state.profile.phone||"")+'" required></div><div class="field"><label>Operating city</label><input class="input" name="city" value="'+v("city",state.profile.city||"")+'" required></div><div class="field"><label>Residential address</label><textarea class="textarea" name="address" required>'+v("address",state.profile.address||"")+'</textarea></div></section><section class="card form-grid"><h2 class="section-title">Vehicle and licence</h2><div class="field"><label>Vehicle type</label><select class="select" name="vehicleType">'+["Motorcycle","Scooter","Electric two-wheeler","Bicycle"].map(x=>'<option '+(draftValue("vehicleType",state.profile.vehicleType||"Motorcycle")===x?'selected':'')+'>'+h(x)+'</option>').join("")+'</select></div>'+vehicleLicenceFields(v)+'</section>'+identitySection()+'<section class="card form-grid"><h2 class="section-title">Referral (optional)</h2><div class="field"><label>Referral code or link</label><input class="input" name="referredByCode" value="'+v("referredByCode",state.profile.referredByCode||installReferralCode())+'" placeholder="6-digit code or referral link"><p class="caption">Use a delivery partner referral code if someone invited you. Your inviter is rewarded only after you complete the required number of successful deliveries. The code cannot be changed after you submit.</p></div></section><label class="notice info"><input type="checkbox" name="verificationConsent" '+(d.verificationConsent?'checked':'')+' required><span>These are my own details, and I agree to identity verification as explained in <b>How we use your data</b>.</span></label><button class="button primary full" type="submit" '+(state.profile.faceMatchStatus!=="unique"?"disabled":"")+'>Submit for secure review</button>'+(state.profile.faceMatchStatus!=="unique"?'<p class="supporting" style="text-align:center">Scan your face above to enable submission.</p>':"")+'</form></div></main>'}
  function screenPending(){const p=state.profile,status=p.status||"submitted",rejected=status==="rejected";return'<main class="screen no-nav"><div class="content" style="min-height:calc(100vh - 50px);display:grid;place-content:center"><section class="card stack-lg" style="text-align:center;max-width:540px"><div class="empty-icon">'+icon(rejected?"warning":"shield","large")+'</div><div><p class="eyebrow">'+h(String(status).replace(/_/g," "))+'</p><h1 class="title" style="font-size:29px;margin-top:7px">'+(rejected?'Your application needs changes.':'Your application is under review.')+'</h1><p class="supporting" style="margin-top:10px">'+(rejected?h(p.reviewNote||"Review the requested changes and resubmit your application."):"Scraveit Admin must approve your identity and vehicle details before delivery jobs become available.")+'</p></div><div class="notice info" style="text-align:left">'+icon("bell","small")+'<span>Refresh to check the latest review status. Production push notifications require activation.</span></div><button class="button primary full" data-action="refresh">'+icon("refresh")+' Check status</button>'+(rejected?'<button class="button tonal full" data-action="go" data-route="onboarding">Update application</button>':'')+'<button class="text-button" data-action="signout">Sign out</button></section></div></main>'}
  function health(){return'<div class="health"><div class="health-item '+(state.location.enabled?'good':'bad')+'"><strong>'+(state.location.enabled?'Ready':'Off')+'</strong>Location</div><div class="health-item '+(state.network?'good':'bad')+'"><strong>'+(state.network?'Online':'Offline')+'</strong>Internet</div><div class="health-item '+(state.online?'good':'')+'"><strong>'+(state.online?'Available':'Paused')+'</strong>Jobs</div></div>'}
  // ---- Pay shown before accepting, and minimum earnings guarantees.
  /** How trip pay is built: base, distance, waiting, time-slot pay and any minimum top-up. */
  function tripPayComponents(o){const c=o&&o.payoutBreakdown&&o.payoutBreakdown.components;if(!c)return"";const rows=[["Base pickup pay",c.basePay],["Distance ("+c.pickupKm+" km pickup + "+c.dropKm+" km drop)",c.distancePay],["Waiting at restaurant",c.waitPay],["Late-night / early-morning",c.slotPay],["Minimum trip pay top-up",c.minimumTopUp]].filter(r=>Number(r[1])!==0);return'<div class="stack" style="gap:6px">'+rows.map(r=>'<div class="price-row"><span>'+h(r[0])+'</span><strong>'+money(r[1])+'</strong></div>').join("")+'<p class="caption">'+(c.estimated?'Estimate from the order. Final pay uses your real pickup distance and waiting time after the restaurant hands over (first 10 minutes of waiting are unpaid).':'Final trip pay.')+' Rain, surge and special bonuses and your customer tip are added on top; tips are always 100% yours.</p></div>'}
  // Founder 17 Nov 2026: show how trip pay is made, "3.3 km · ₹20 + ₹5/km" (pay = the customer's delivery fee).
  // The rate comes from the same settings the customer bill uses; the line shows only when it adds up to the trip pay,
  // so a later rate change or a waived fee never shows a wrong sum.
  /** Founder 17 Nov 2026: each payout option shows its bank transfer fee (settings/payoutFees), taken from the weekly payout. */
const PAYOUT_FEE_DEFAULT={deductFromPayout:true,gstBps:1800,bands:[{upToPaise:100000,neftPaise:300,impsPaise:600,upiPaise:600},{upToPaise:2500000,neftPaise:500,impsPaise:800,upiPaise:800},{upToPaise:0,neftPaise:800,impsPaise:1500,upiPaise:1500}]};
let payoutFeesAsked=false;
function payoutFeeTable(){if(!payoutFeesAsked){payoutFeesAsked=true;fs.collection("settings").doc("payoutFees").get().then(s=>{const d=s.exists?s.data():null;if(d&&Array.isArray(d.bands)&&d.bands.length){state.payoutFees={upiAvailable:d.upiAvailable===true,deductFromPayout:d.deductFromPayout!==false,gstBps:Number(d.gstBps)||0,bands:d.bands.map(b=>({upToPaise:Number(b.upToPaise)||0,neftPaise:Number(b.neftPaise)||0,impsPaise:Number(b.impsPaise)||0,upiPaise:Number(b.upiPaise)||0})).sort((a,b)=>(a.upToPaise||1e15)-(b.upToPaise||1e15))};refreshPayoutPickers()}}).catch(()=>{})}return state.payoutFees||PAYOUT_FEE_DEFAULT}
function payoutFeePaise(method,amountPaise,t){const b=t.bands.find(x=>!x.upToPaise||amountPaise<=x.upToPaise)||t.bands[t.bands.length-1];if(!b)return 0;const base=method==="neft"?b.neftPaise:method==="imps"?b.impsPaise:b.upiPaise;return Math.round(base*(10000+t.gstBps)/10000)}
function rupees2(paise){const v=Math.round(Number(paise)||0)/100;return"₹"+v.toLocaleString("en-IN",{minimumFractionDigits:v%1?2:0,maximumFractionDigits:2})}
function upiPayoutOpen(){return payoutFeeTable().upiAvailable===true}
function payoutMethodPicker(selected,exampleRupees,disabledAttr){const t=payoutFeeTable(),upiOpen=t.upiAvailable===true,pick=selected==="upi"&&!upiOpen?"imps":["upi","imps","neft"].includes(selected)?selected:"neft",rows=[["neft","NEFT","Same day"],["imps","IMPS","In minutes"],["upi","UPI","In minutes"]],cols=upiOpen?["neft","imps","upi"]:["neft","imps"],fees=t.deductFromPayout&&t.bands.length?'<table class="pay-fees"><thead><tr><th>Payout amount</th>'+cols.map(m=>'<th>'+m.toUpperCase()+'</th>').join("")+'</tr></thead><tbody>'+t.bands.map((x,i)=>{const prev=(t.bands[i-1]||{}).upToPaise||0,amount=x.upToPaise||prev+1;return'<tr><td>'+(x.upToPaise?'Up to '+money(x.upToPaise/100):'Above '+money(prev/100))+'</td>'+cols.map(m=>'<td>'+rupees2(payoutFeePaise(m,amount,t))+'</td>').join("")+'</tr>'}).join("")+'</tbody></table><p class="caption">Fee is taken from your pay · GST included</p>':'';return'<div class="pay-methods" data-ex="'+exampleRupees+'">'+rows.map(([m,title,speed])=>{if(m==="upi"&&!upiOpen)return'<label class="pay-method soon"><input type="radio" name="preferredMethod" value="upi" disabled><span class="pay-line"><strong>UPI</strong><span class="pay-speed">Available soon</span></span></label>';return'<label class="pay-method"><input type="radio" name="preferredMethod" value="'+m+'"'+(m===pick?' checked':'')+(disabledAttr||"")+'><span class="pay-line"><strong>'+title+'</strong><span class="pay-speed">'+speed+'</span></span>'+(t.deductFromPayout?'':'<span class="pay-fee">No fee</span>')+'</label>'}).join("")+fees+'</div>'}
function refreshPayoutPickers(){document.querySelectorAll(".pay-methods").forEach(el=>{const c=el.querySelector("input:checked"),d=el.querySelector("input:disabled:not([value=upi])")?" disabled":"";el.outerHTML=payoutMethodPicker(c?c.value:"neft",Number(el.dataset.ex)||2000,d)})}
let feeRateAsked=false;
  function loadFeeRate(){if(feeRateAsked)return;feeRateAsked=true;fs.collection("settings").doc("customer").get().then(s=>{const d=s.data()||{},base=Number(d.deliveryBaseFee),perKm=Number(d.deliveryPerKm);if(d.deliveryBaseFee!=null&&d.deliveryPerKm!=null&&Number.isFinite(base)&&Number.isFinite(perKm)){state.feeRate={base,perKm,backPerKm:Math.max(0,Number(d.returnTripPerKm)||0),backFreeKm:Number.isFinite(Number(d.returnTripFreeKm))?Number(d.returnTripFreeKm):2,road:d.deliveryDistanceMode==="road"};render({preserveScroll:true})}}).catch(()=>{})}
  function feeKmNote(b){const km=Number(b&&b.feeKm);if(!b||b.feeKm==null||!Number.isFinite(km))return"";loadFeeRate();const r=state.feeRate;if(!r)return"";const k=Math.max(0,km),pay=Number(b.tripPay),plain=r.base+r.perKm*k,back=r.backPerKm>0?r.backPerKm*Math.max(0,k-r.backFreeKm):0;const near=(x)=>Math.abs(x-pay)<0.51;const km1=(Math.round(km*10)/10)+' km'+(r.road?' by road':'');if(near(plain))return'<p class="caption pay-km">'+km1+' · '+money(r.base)+' + '+money(r.perKm)+'/km</p>';if(back>0&&near(plain+back))return'<p class="caption pay-km">'+km1+' · '+money(r.base)+' + '+money(r.perKm)+'/km + ride back '+money(back)+'</p>';return""}
  function payoutBreakdownLine(o){const b=o&&o.payoutBreakdown;if(!b||typeof b!=="object")return"";const parts=[["Trip pay",b.tripPay],["Waiting pay",b.waitPay],["Bonus",b.incentives],["Customer tip (100% yours)",b.tip]].filter(x=>Number(x[1])>0);return parts.length?'<div class="pay-breakdown">'+parts.map(x=>'<span><small>'+h(x[0])+'</small><strong>'+money(x[1])+'</strong></span>').join("")+'</div>'+feeKmNote(b):""}
  function rupeesPrecise(paise){const v=Math.round(Number(paise||0)),r=Math.floor(Math.abs(v)/100),c=Math.abs(v)%100;return(v<0?"−":"")+"₹"+r.toLocaleString("en-IN")+(c?"."+String(c).padStart(2,"0"):"")}
  function guaranteeOfferCard(offer){const g=offer.guarantee,done=["COMPLETED","completed","PAID"].includes(String(offer.status)),failed=["FAILED","EXPIRED"].includes(String(offer.status)),milestones=Array.isArray(offer.milestones)?offer.milestones:[],top=milestones.length?milestones[milestones.length-1]:null,target=g.nextTarget||g.tierTarget||(top&&top.target)||0,guaranteed=g.guaranteedPaise||g.nextGuaranteedPaise||(top&&top.rewardAmountPaise)||0,remaining=Math.max(0,target-g.completedDeliveries),credited=Number(offer.creditedRewardPaise||0),statusLabel=g.status==="seats_full"?["warning","All places taken"]:g.status==="budget_exhausted"?["warning","Guarantee budget used up"]:g.status==="paused"?["warning","Paused by Scraveit"]:done?["success","Completed"]:failed?["danger","Conditions not met"]:["success","In progress"];
    const rows=[["Target",target+" deliveries"],["Completed",g.completedDeliveries+" / "+target],["Eligible earnings",rupeesPrecise(g.eligibleEarningsPaise)],["Guaranteed amount",rupeesPrecise(guaranteed)]];
    if(!done)rows.push([g.tierTarget?"Top-up if you finish now":"Possible top-up",rupeesPrecise(g.tierTarget?g.topUpPaise:Math.max(0,guaranteed-g.eligibleEarningsPaise))]);
    const tiers=milestones.length>1?'<div class="guarantee-tiers">'+milestones.map(m=>'<span class="'+(g.completedDeliveries>=m.target?'reached':'')+'"><strong>'+h(m.target)+'</strong><small>'+rupeesPrecise(m.rewardAmountPaise)+'</small></span>').join("")+'</div>':"";
    const result=done?'<div class="notice success">'+icon("check","small")+'<div class="stack" style="gap:4px"><span>Actual eligible earnings '+rupeesPrecise(g.eligibleEarningsPaise)+'</span><span>Guarantee '+rupeesPrecise(g.guaranteedPaise)+'</span><strong>Scraveit top-up '+rupeesPrecise(credited)+'</strong><span>Final eligible earnings '+rupeesPrecise(g.eligibleEarningsPaise+credited)+'</span></div></div>':"";
    const conditions=(offer.conditions||[]).filter(Boolean).slice(0,6);
    return'<article class="card stack guarantee-card"><div class="cluster between"><div><p class="eyebrow">Minimum earnings guarantee</p><h3 class="card-title">'+h(offer.title||"Earnings guarantee")+'</h3>'+(offer.periodLabel?'<p class="caption">'+h(offer.periodLabel)+'</p>':'')+'</div><span class="status '+statusLabel[0]+'">'+h(statusLabel[1])+'</span></div>'+tiers+'<div class="stack" style="gap:8px">'+rows.map(r=>'<div class="cluster between"><span class="supporting">'+h(r[0])+'</span><strong>'+h(r[1])+'</strong></div>').join("")+'</div>'+(!done&&!failed&&remaining?'<p class="supporting"><strong>'+remaining+' more qualifying deliver'+(remaining===1?'y':'ies')+'</strong> needed.</p>':'')+(conditions.length?'<ul class="caption guarantee-conditions">'+conditions.map(c=>'<li>'+h(c)+'</li>').join("")+'</ul>':'')+result+'<p class="caption">If you qualify and your eligible earnings are below '+rupeesPrecise(guaranteed)+', Scraveit pays the difference. If you earn more, you keep the higher amount. Customer tips are always yours'+(Array.isArray(g.components)&&g.components.includes("tips")?' and count toward this guarantee':' and do not reduce the top-up')+'.</p></article>'}
  function offerCard(o){const trip=tripOfferNote(o);return'<article class="card job-card'+(o.bundle?' trip-offer':'')+'"><div class="cluster between"><span class="status success">'+(o.bundle?(o.bundle.kind==="batch"?'EXTRA ORDER · ON YOUR WAY':'EXTRA PICKUP · YOUR TRIP'):'RESTAURANT ACCEPTED')+'</span><strong>'+money(o.payout||0)+' payout</strong></div>'+(trip?'<p class="trip-note">'+h(trip)+'</p>':'')+'<p class="caption">Reserve now. Pickup unlocks when the kitchen marks the order ready.</p>'+payoutBreakdownLine(o)+'<div class="job-route"><div class="route-dots"><span></span><i></i><span></span></div><div class="stack"><div><strong>'+h(o.restaurantName||"Restaurant")+'</strong><p class="supporting">'+h(o.restaurantArea||o.restaurantAddress||"Pickup details")+'</p></div><div><strong>'+h(o.approximateDropZone||"Drop zone shown after assignment")+'</strong><p class="supporting">Exact customer address stays private until restaurant handover.</p></div></div></div><div class="job-metrics"><div class="job-metric"><strong>'+h(o.distanceKm||"—")+(o.distanceKm?' km':'')+'</strong><span>Approx. pickup</span></div><div class="job-metric"><strong>'+h(o.itemCount||0)+'</strong><span>Items</span></div><div class="job-metric"><strong>'+h(o.estimatedMinutes||"—")+'</strong><span>Est. min</span></div></div><button class="button primary full" data-action="offer-detail" data-offer-id="'+h(o.id)+'">Review delivery offer</button></article>'}
  function currentCard(o){const idx=Math.max(0,["Assigned","Handed to rider","Out for delivery","Near you","Arrived"].indexOf(o.status)),stop=tripLabel(o),next=nextTripPickup();return'<button class="card trip-card'+(next&&next.id===o.id?' trip-next':'')+'" data-action="open-job" data-job-id="'+h(o.id)+'"><div class="cluster between"><span class="status">'+h(statusName(o.status))+'</span>'+(stop?'<span class="status trip-stop">'+h(stop)+(next&&next.id===o.id?' · next':'')+'</span>':'')+'<span class="caption">'+h(ago(o.updatedAt||o.createdAt))+'</span></div><h2 class="section-title">'+h(o.restaurant||"Active delivery")+'</h2><p class="supporting">'+h(o.customerName||"Customer assigned")+'</p><div class="progress"><span style="width:'+Math.min(100,(idx+1)*20)+'%"></span></div><span class="trip-card-cta">Continue trip '+icon("chevron","small")+'</span></button>'}
  function jobSearchInput(){return'<div class="input-wrap"><span class="input-icon">'+icon("search")+'</span><input id="job-search" class="input with-icon" value="'+h(state.jobQuery)+'" placeholder="Search restaurant, order or area" autocomplete="off" enterkeyhint="search"></div>'}
  function offerResultsMarkup(){const offers=availableOffers();return state.loading?loading("Checking offers…"):offers.length?'<div class="stack">'+offers.map(offerCard).join("")+'</div>':empty("jobs",shownOnline()?'No matching offers nearby':'Go online to get orders',shownOnline()?'New eligible offers will appear here.':'Use the switch at the top. Keep Location on.')}
  function activeResultsMarkup(){const list=activeJobs().filter(jobMatches);return list.length?'<div class="stack">'+list.map(currentCard).join("")+'</div>':empty("active",searchKey(state.jobQuery)?"No matching delivery":"No active delivery",searchKey(state.jobQuery)?"Try another order, restaurant or area.":"Accept an eligible offer when you are online.",searchKey(state.jobQuery)?"":"go-jobs",searchKey(state.jobQuery)?"":"View available jobs")}
  function riderTodaySummary(){const dashboard=rewardsDashboard();if(!dashboard)return null;const today=rewardTodayBreakdown(dashboard),todayKey=earningDateKey(),sel=dashboard.selectedDay||{},trips=sel.dayKey===todayKey?Number(sel.completedTrips||0):null,tracker=rewardLoginTracker(dashboard),goal=(dashboard.offers||[]).map(offer=>({offer,next:rewardNextMilestone(offer)})).find(x=>x.next&&!x.next.reached&&Number(x.next.remainingTrips||0)>0&&["available","locked","eligible_delivery_match_required","ACTIVE","IN_PROGRESS"].includes(String(x.offer.status||"")));return{total:today.tripEarningsPaise+today.incentivePaise+today.referralPaise+today.tipPaise,trip:today.tripEarningsPaise,bonus:today.incentivePaise+today.referralPaise,tips:today.tipPaise,trips,tracker:tracker&&tracker.enabled?tracker:null,goal:goal?{remaining:Number(goal.next.remainingTrips||0),reward:Number(goal.next.rewardAmountPaise||0)}:null,cod:Number(dashboard.financial&&dashboard.financial.cod&&dashboard.financial.cod.outstandingPaise||0)}}
  function homeHealthNotice(){const issues=[];if(state.locationChecked&&!state.location.enabled)issues.push("Location is off");if(!state.network)issues.push("No internet");if(!issues.length)return"";return'<button class="notice danger home-health" data-action="location-settings">'+icon("warning","small")+'<span><strong>'+h(issues.join(" · "))+'</strong> Orders pause until this is fixed.</span></button>'}
