  function screenActive(){return'<main class="screen"><div class="content page">'+banner()+'<header class="cluster between"><div><p class="eyebrow">Active deliveries</p><h1 class="title">One clear task at a time.</h1><p class="supporting">Exact customer address unlocks only after restaurant handover.</p></div><button class="icon-button" data-action="refresh">'+icon("refresh")+'</button></header>'+jobSearchInput()+'<div id="active-results">'+activeResultsMarkup()+'</div></div>'+nav()+'</main>'}
  // Waiting at the restaurant: Scraveit pays ₹1 a minute after the first 10, up to ₹30.
