  function waitSince(o){const p=state.jobPointers[o.id]||{};return Number(p.arrivedRestaurantAt||o.arrivedRestaurantAt||0)}
  function waitText(since){const m=Math.max(0,Math.floor((Date.now()-since)/60000)),pay=Math.min(30,Math.max(0,m-10));return pay>0?"Waiting "+m+" min · ₹"+pay+" waiting pay":"Waiting "+m+" min · waiting pay starts in "+(10-m)+" min"}
  function waitMeter(o){const since=waitSince(o);if(!since)return"";return'<div class="notice success">'+icon("clock","small")+'<span><strong data-wait-since="'+since+'">'+h(waitText(since))+'</strong><br><small>First 10 min free, then ₹1 a minute, up to ₹30. Paid by Scraveit, added after delivery.</small></span></div>'}
  if(!window.__scraveitWaitTick)window.__scraveitWaitTick=setInterval(()=>{document.querySelectorAll("[data-wait-since]").forEach(el=>{el.textContent=waitText(Number(el.dataset.waitSince))})},15000);
  function workflowAction(o){const pointer=state.jobPointers[o.id]||{},arrivalPending=state.pendingJobAction===o.id;if(o.status==="Assigned"&&pointer.phase!=="at_restaurant"){setTimeout(warmArrivalCheck,0);return'<div class="stack"><button class="button primary full task-action" data-action="navigate-restaurant" data-job-id="'+h(o.id)+'">'+icon("navigation")+' Navigate to restaurant</button>'+(arrivalPending?'<button class="button secondary full" disabled><span class="spinner"></span> Verifying restaurant arrival…</button>':swipeConfirm('Swipe: arrived at restaurant','data-action="arrived-restaurant" data-job-id="'+h(o.id)+'"'))+'</div>'}if(o.status==="Assigned"&&pickupJustConfirmed(o))return'<button class="button primary full" disabled><span class="spinner"></span> Pickup confirmed. Loading the delivery…</button>';if(o.status==="Assigned"&&arrivalPending)return'<button class="button primary full" disabled><span class="spinner"></span> Saving parcel photo…</button>';if(o.status==="Assigned")return'<div class="stack">'+waitMeter(o)+'<div class="notice info">'+icon("clock","small")+'<span>Collect the parcel for order ID ending <b>'+h(orderTail(o))+'</b>. Take a photo of the parcel with the bill or order ID showing.</span></div><label class="button primary full task-action" for="pickup-photo-input" data-pickup-photo-job="'+h(o.id)+'">'+icon("camera")+' Take parcel photo · picked up</label></div>';if(o.status==="Handed to rider"&&batchHold(o))return'<div class="notice info">'+icon("navigation","small")+'<span>'+h(batchHold(o))+'</span></div>';if(o.status==="Handed to rider")return arrivalPending?'<button class="button primary full" disabled><span class="spinner"></span> Confirming pickup…</button>':swipeConfirm(o.batch&&batchDropRank(o)>0?'Swipe: start next delivery':'Swipe: picked up, start delivery','data-action="confirm-pickup" data-job-id="'+h(o.id)+'"');if(["Out for delivery","Near you"].includes(o.status))return'<div class="stack"><button class="button primary full task-action" data-action="navigate-customer" data-job-id="'+h(o.id)+'">'+icon("navigation")+' Navigate to customer</button>'+(arrivalPending?'<button class="button secondary full" disabled><span class="spinner"></span> Checking your location…</button>':swipeConfirm('Swipe: at the delivery location','data-action="arrived-customer" data-job-id="'+h(o.id)+'"'))+'</div>';if(o.status==="Arrived")return swipeConfirm('Swipe: verify and complete','data-action="complete-delivery" data-job-id="'+h(o.id)+'"',false,"success");return''}
