  function shiftDayHasOffer(dayKey){const dashboard=rewardsDashboard(),bar=dashboard&&(dashboard.weekBars||[]).find(b=>b.dayKey===dayKey);return !!(bar&&(bar.hasOffer||bar.hasSpecialOffer))}
